@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Marcellus&display=swap');
:root{--bg:#101510;--panel:#171d18;--panel2:#1d241e;--line:#30392f;--muted:#879083;--text:#e8e8d9;--gold:#e4b85e;--gold2:#a7803d;--green:#a4bc83;--red:#d67566;--blue:#8eb7cb;--purple:#b49bdd;--font:'DM Sans',sans-serif;--display:'Marcellus',serif}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 75% -10%,#293329 0,transparent 38%),var(--bg);color:var(--text);font-family:var(--font);font-size:14px;min-height:100vh}button{font:inherit;color:inherit;cursor:pointer}button:disabled{opacity:.42;cursor:not-allowed}.app-shell{min-height:100vh;padding-bottom:0}.topbar{height:78px;border-bottom:1px solid #293129;background:rgba(15,20,16,.91);display:flex;align-items:center;padding:0 4.2%;gap:35px;position:sticky;top:0;z-index:10;backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:12px;color:var(--text);text-decoration:none;font:20px var(--display);letter-spacing:2px;white-space:nowrap}.brand-mark{color:var(--gold);font-size:31px;text-shadow:0 0 18px #e4b85e55}.brand small{font:8px var(--font);display:block;color:#9b9e8e;letter-spacing:2.1px;margin-top:3px}.resource-strip{display:flex;gap:10px;margin-left:auto}.resource{height:43px;min-width:132px;border:1px solid #333b31;background:#1a201b;border-radius:7px;display:flex;align-items:center;padding:5px 8px;gap:9px}.resource>span:nth-child(2){display:flex;flex-direction:column;line-height:1.05}.resource b{font-size:14px;letter-spacing:.3px}.resource small{font-size:8px;color:#92988b;letter-spacing:1.5px;margin-top:3px}.coin{color:var(--gold);font-size:20px}.gem{color:#86c5cf;font-size:17px;text-shadow:0 0 10px #86c5cf66}.plus{margin-left:auto;background:#273029;border:1px solid #465044;color:var(--green);width:23px;height:23px;border-radius:5px;font-weight:700}.profile{display:flex;align-items:center;gap:10px;border:0;border-left:1px solid var(--line);padding-left:23px;background:none;text-align:left;font-size:10px;letter-spacing:1.2px;color:#d9dccf}.profile small{display:block;color:#9da394;font-size:10px;letter-spacing:.3px;margin-top:3px}.avatar-mini{width:34px;height:34px;border-radius:50%;border:1px solid #827142;color:var(--gold);display:grid;place-items:center;background:radial-gradient(circle,#4b4128,#25241c);font-size:17px}.chevron{color:#81887b;font-size:18px}.layout{max-width:1450px;margin:0 auto;min-height:calc(100vh - 78px);display:grid;grid-template-columns:258px minmax(0,1fr);padding:0 34px 0 0}.side-rail{border-right:1px solid #293129;padding:27px 19px 18px 26px;display:flex;flex-direction:column;min-height:calc(100vh - 78px)}.season-card{height:155px;border:1px solid #52462e;border-radius:8px;padding:15px 16px;background:linear-gradient(120deg,#322a1b,#1d211a 70%);position:relative;overflow:hidden}.season-card:after{content:'✦';position:absolute;right:13px;top:24px;color:#bd965344;font-size:73px}.season-kicker{font-size:9px;letter-spacing:1.6px;color:var(--gold)}.season-kicker span{color:#979888}.season-title{font:19px/1.26 var(--display);margin-top:11px;position:relative;z-index:1}.season-progress,.quest-progress{height:4px;background:#3a3b2e;border-radius:8px;margin-top:12px;overflow:hidden}.season-progress span,.quest-progress span{display:block;background:linear-gradient(90deg,#ad8549,#e5c777);height:100%;border-radius:8px}.season-card>small{font-size:9px;color:#a6a798;display:block;margin-top:6px}.season-card>small b{color:#e9dfc2}.side-label{color:#7f887b;font-size:9px;letter-spacing:2px;margin:28px 0 15px}.side-region{display:flex;align-items:center;gap:12px;padding:3px 4px 20px;border-bottom:1px solid #293129}.region-icon{width:37px;height:37px;background:#263226;color:#a5bd88;border:1px solid #45523e;display:grid;place-items:center;border-radius:7px;font-size:21px}.side-region small,.side-quest small{display:block;color:#8c9588;font-size:8px;letter-spacing:1.2px;margin-bottom:5px}.side-region b{font:13px var(--display)}.side-quest{display:flex;align-items:flex-start;gap:10px;padding:17px 3px;border-bottom:1px solid #293129}.quest-icon{color:var(--gold);font-size:18px}.side-quest>div{flex:1}.side-quest b{font-size:10px;font-weight:600}.quest-progress{margin:9px 0 5px;height:3px}.side-quest small:last-child{font-size:9px;margin:0}.quest-reward{color:#ded6bb;font-size:9px;white-space:nowrap}.quest-reward i{color:#91d1d8;font-style:normal}.side-spacer{flex:1;min-height:35px}.offline-card{background:#20281f;border:1px solid #394536;border-radius:7px;padding:12px 10px;display:grid;grid-template-columns:26px 1fr;gap:2px 6px;align-items:center}.offline-card>span{color:var(--green);font-size:20px;grid-row:span 2}.offline-card b{font-size:10px;display:block}.offline-card small{display:block;color:#929b8d;font-size:9px;margin-top:3px}.offline-card button{grid-column:2;background:#526344;color:#e3e5d8;border:0;border-radius:4px;font-size:8px;font-weight:700;letter-spacing:1px;padding:7px;margin-top:9px}.side-footer{font-size:8px;color:#7f887d;letter-spacing:.7px;margin-top:14px;display:flex;align-items:center;gap:6px}.online-dot{width:6px;height:6px;background:#8db878;border-radius:50%;box-shadow:0 0 8px #8db878}.main-panel{padding:27px 0 32px 32px;min-width:0}.tab-content{max-width:1120px;margin:0 auto}.eyebrow{font-size:9px;color:var(--gold);letter-spacing:2.1px;font-weight:700}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:19px}.page-heading h1{font:29px var(--display);margin:7px 0 0;letter-spacing:.2px}.subheading{color:#92998c;font-size:11px;margin-top:5px}.section-title{font:17px var(--display);margin:0}.section-label{color:#8e978a;font-size:9px;letter-spacing:1.5px}.card{border:1px solid var(--line);background:linear-gradient(140deg,#1c231d,#171d18);border-radius:8px}.muted{color:var(--muted)}.gold-text{color:var(--gold)}.green-text{color:var(--green)}.purple-text{color:var(--purple)}.btn{border:1px solid #6c5735;border-radius:5px;background:linear-gradient(180deg,#8a6c38,#654d2b);color:#fff2d6;padding:10px 15px;font-size:10px;font-weight:700;letter-spacing:1.2px;transition:.18s}.btn:hover:not(:disabled){filter:brightness(1.2);transform:translateY(-1px)}.btn.secondary{background:#222a22;border-color:#485444;color:#dce1d4}.btn.ghost{background:transparent;border-color:#424b40;color:#bac2b3}.btn.small{padding:7px 10px;font-size:9px}.badge{display:inline-flex;align-items:center;gap:5px;border:1px solid #49513e;border-radius:20px;background:#242c23;padding:5px 9px;color:#c2cbae;font-size:9px;letter-spacing:.5px}.badge:before{content:'';width:5px;height:5px;background:var(--green);border-radius:50%}.divider{height:1px;background:#30382f;margin:14px 0}.bottom-nav{display:none}.toast{position:fixed;left:50%;bottom:28px;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#293229;border:1px solid #65704f;border-radius:6px;padding:11px 18px;color:#e8eadc;font-size:12px;box-shadow:0 10px 30px #0008;z-index:50;transition:.2s}.toast.show{transform:translate(-50%,0);opacity:1}.modal-backdrop{position:fixed;inset:0;background:#050806bb;display:grid;place-items:center;z-index:40;padding:20px}.modal{width:min(430px,100%);background:#1b231d;border:1px solid #53583c;border-radius:10px;padding:25px;box-shadow:0 25px 80px #000b}.modal h2{font:23px var(--display);margin:0 0 8px}.modal p{color:#a7ad9f;line-height:1.6;font-size:12px}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}
/* Battle */
.battle-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(250px,.78fr);gap:16px}.battle-stage{height:368px;position:relative;overflow:hidden;border:1px solid #444839;border-radius:9px;background:linear-gradient(180deg,#141b19 0%,#28382d 53%,#20251d 100%)}.battle-stage:before{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#0e130ff2 0%,transparent 55%),radial-gradient(ellipse at 72% 45%,#a9814b24,transparent 38%)}.stage-moon{position:absolute;width:74px;height:74px;border-radius:50%;background:#c2ab7750;right:14%;top:12%;box-shadow:0 0 55px #b29a5740}.ruin{position:absolute;bottom:25%;background:linear-gradient(90deg,#161c19,#31382d);clip-path:polygon(0 28%,20% 28%,20% 0,34% 0,34% 20%,57% 20%,57% 8%,74% 8%,74% 30%,100% 30%,100% 100%,0 100%);opacity:.74}.ruin.one{right:4%;width:155px;height:125px}.ruin.two{left:10%;width:130px;height:92px;opacity:.5}.ground{position:absolute;bottom:0;height:30%;width:100%;background:linear-gradient(0deg,#151914,#242d23aa);border-top:1px solid #51513b66}.combatants{position:absolute;inset:auto 0 0;height:69%;display:flex;align-items:flex-end;justify-content:space-evenly;padding:0 7% 7%;z-index:1}.fighter{position:relative;font-size:100px;line-height:1;text-shadow:0 8px 18px #0009;filter:drop-shadow(0 0 9px #b9a15b20);animation:bob 2.4s ease-in-out infinite}.fighter.enemy{font-size:92px;animation-delay:.7s;filter:drop-shadow(0 8px 9px #0008)}@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}.fighter .health{position:absolute;bottom:-12px;left:50%;transform:translateX(-50%);width:112px;background:#222;height:5px;border:1px solid #7775;border-radius:5px;overflow:hidden}.health span{display:block;height:100%;background:#ca6652}.fighter.hero .health span{background:#95b66f}.combat-label{position:absolute;bottom:20px;font-size:8px;letter-spacing:1.5px;color:#d2d3bd;text-align:center;width:120px;left:50%;transform:translateX(-50%)}.stage-top{position:absolute;top:14px;left:16px;z-index:3;display:flex;align-items:center;gap:9px}.stage-top .stage-name{font:14px var(--display)}.stage-top small{display:block;color:#a2a796;font-size:9px;margin-top:4px}.ambient{position:absolute;top:16px;right:15px;z-index:3;border:1px solid #58634a;background:#202a20dd;border-radius:4px;padding:6px 9px;color:#c4d2a4;font-size:9px}.battle-footer{display:flex;align-items:center;gap:12px;position:absolute;bottom:12px;left:15px;right:15px;z-index:3}.battle-footer .stage-track{flex:1}.track-head{display:flex;justify-content:space-between;color:#c3c4b5;font-size:9px;margin-bottom:6px}.track{height:5px;background:#505344;border-radius:5px;overflow:hidden}.track span{height:100%;display:block;background:linear-gradient(90deg,#a6864c,#e2c172);transition:width .25s}.battle-footer .btn{white-space:nowrap}.combat-side{display:flex;flex-direction:column;gap:12px}.enemy-card{padding:15px}.enemy-head{display:flex;align-items:center;justify-content:space-between}.enemy-head b{font:16px var(--display)}.enemy-card .muted{font-size:9px;margin-top:4px}.boss-art{height:92px;display:grid;place-items:center;font-size:53px;color:#bd9c66;text-shadow:0 0 25px #b7864a44}.boss-stats{display:grid;grid-template-columns:1fr 1fr;gap:9px}.stat-chip{background:#222922;padding:8px;border-radius:5px}.stat-chip small{display:block;color:#929a8e;font-size:8px;letter-spacing:.8px}.stat-chip b{display:block;font-size:11px;margin-top:4px}.battle-stats{padding:13px 15px;flex:1}.battle-stats h3{font:14px var(--display);margin:0 0 11px}.loot-line{display:flex;justify-content:space-between;font-size:10px;color:#b1b8aa;margin:9px 0}.loot-line b{color:#e3c574;font-weight:600}.skill-row{display:flex;gap:8px;margin-top:11px}.skill{width:45px;height:45px;border:1px solid #576347;background:radial-gradient(#37432d,#222921);border-radius:6px;display:grid;place-items:center;font-size:19px;position:relative}.skill small{position:absolute;bottom:2px;right:3px;font-size:7px;color:#b1bb9c}.combat-feed{font-size:9px;color:#9ea696;margin-top:8px;min-height:12px}.battle-bottom{margin-top:13px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:11px}.mini-info{padding:11px 13px;display:flex;align-items:center;gap:10px}.mini-info .icon{font-size:20px;color:var(--gold)}.mini-info small{display:block;color:#899184;font-size:8px;letter-spacing:1px}.mini-info b{font-size:11px;display:block;margin-top:3px}

/* Shared panels and screens */
.world-banner{min-height:145px;border:1px solid #49513c;border-radius:8px;padding:20px 23px;position:relative;overflow:hidden;background:linear-gradient(90deg,#202a20ee,#202a2099),radial-gradient(ellipse at 82% 30%,#94a95a55,transparent 30%),linear-gradient(130deg,#314a35,#22281e 60%,#3b3020);margin-bottom:16px}.world-banner:after{content:'♧';position:absolute;right:9%;top:-19px;font-size:160px;color:#bbcf8a1b;line-height:1}.world-banner h2{font:24px var(--display);margin:7px 0}.world-banner p{color:#aab1a0;font-size:10px;margin:0;max-width:440px}.world-meta{display:flex;gap:7px;margin-top:12px;position:relative;z-index:1}.region-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.region-card{min-height:128px;padding:12px 12px 10px;position:relative;overflow:hidden;cursor:pointer;transition:.18s;border-color:#374035}.region-card:hover:not(.locked){transform:translateY(-2px);border-color:#788157}.region-card.active{border-color:#b69453;box-shadow:inset 0 0 0 1px #b6945333}.region-card.locked{opacity:.5;filter:saturate(.4);cursor:not-allowed}.region-card:after{content:attr(data-symbol);position:absolute;right:2px;bottom:-13px;font-size:57px;color:#bdc99412}.region-card .region-num{font-size:8px;letter-spacing:1.2px;color:#929b8d}.region-card h3{font:13px var(--display);margin:10px 0 6px;max-width:120px}.region-card p{color:#939c8d;font-size:8px;line-height:1.4;margin:0}.region-card .node-count{position:absolute;bottom:10px;right:10px;color:#cfba7b;font-size:8px}.world-lower{display:grid;grid-template-columns:1.35fr .85fr;gap:12px;margin-top:15px}.nodes-card,.expedition-card{padding:16px}.node-list{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:14px}.node{height:56px;border:1px solid #384135;background:#202820;border-radius:6px;display:grid;place-items:center;position:relative;cursor:pointer}.node span{font-size:15px}.node small{font-size:7px;color:#9da494}.node.done{border-color:#7f9862;background:#283329;color:#a6c381}.node.current{border-color:#c49b4d;box-shadow:0 0 12px #c49b4d33}.node.locked{opacity:.36;cursor:not-allowed}.node.boss{border-color:#794d41;background:#30231f;color:#d5836b}.node.boss small{color:#d39a7d}.expedition-card{background:linear-gradient(145deg,#22271f,#1a201b)}.expedition-card p{font-size:10px;line-height:1.6;color:#9ca496}.expedition-art{height:69px;display:flex;align-items:center;justify-content:center;gap:22px;font-size:26px;color:#a9bd87;background:radial-gradient(ellipse,#4a59382c,transparent 70%);margin:8px 0}.expedition-details{display:flex;justify-content:space-between;font-size:9px;color:#a4ab9c;margin-bottom:12px}.expedition-details b{color:#d9cfad}.expedition-card .btn{width:100%}.tabs-line{display:flex;gap:6px;border-bottom:1px solid #343c32;margin-bottom:14px}.tabs-line button{border:0;background:transparent;color:#929a8c;padding:9px 13px;font-size:9px;letter-spacing:1px;border-bottom:2px solid transparent}.tabs-line button.active{color:#e0c274;border-bottom-color:#c4a052}.hero-grid{display:grid;grid-template-columns:.82fr 1.18fr;gap:14px}.hero-portrait{height:260px;position:relative;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at 50% 45%,#68754c55,transparent 55%),linear-gradient(145deg,#252d24,#171d19);font-size:132px}.hero-portrait:after{content:'✦';position:absolute;color:#d7ba6c20;font-size:200px;right:0;top:-20px}.hero-level{position:absolute;left:15px;top:14px;font-size:9px;letter-spacing:1px;color:#d4cda9}.hero-xp{position:absolute;bottom:13px;left:15px;right:15px}.hero-xp div{height:4px;background:#464b3a;border-radius:3px;margin-top:7px}.hero-xp span{display:block;width:45%;height:100%;background:#c9a858}.hero-summary{padding:16px}.hero-summary h2{font:19px var(--display);margin:0}.hero-summary>p{font-size:10px;color:#929a8d}.stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:15px}.stats-grid .stat-chip{padding:10px}.gear-panel{margin-top:14px;padding:15px}.gear-slots{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.gear-slot{min-height:70px;border:1px solid #353d34;background:#202720;border-radius:6px;padding:9px;cursor:pointer}.gear-slot:hover{border-color:#7d744b}.gear-slot>div:first-child{font-size:16px;float:left;margin-right:8px}.gear-slot small{display:block;color:#8f988a;font-size:8px;letter-spacing:.8px}.gear-slot b{font-size:9px;display:block;margin-top:5px}.rarity-common{color:#aab0a5}.rarity-uncommon{color:#83bd85}.rarity-rare{color:#83bce3}.rarity-epic{color:#b398e0}.rarity-legendary{color:#e5b35e}.rarity-mythic{color:#ea8271}.inventory-card{padding:15px;margin-top:13px}.inventory-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:7px;margin-top:11px}.inventory-item{border:1px solid #384036;background:#202720;border-radius:5px;padding:8px 5px;text-align:center;min-height:65px;cursor:pointer}.inventory-item.selected{border-color:#d0ad5d;background:#312d20}.inventory-item .item-icon{font-size:18px}.inventory-item small{display:block;font-size:7px;color:#a3aa9d;margin-top:4px}.forge-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:14px}.forge-box{padding:18px}.forge-box h2{font:17px var(--display);margin:0}.forge-box>p{font-size:10px;color:#9aa293;line-height:1.55}.forge-options{display:flex;gap:7px;margin:13px 0}.forge-options button{background:#242b24;border:1px solid #40493d;padding:7px 11px;border-radius:4px;color:#9ca594;font-size:9px}.forge-options button.active{border-color:#b39455;color:#dec578}.forge-target{height:120px;border:1px dashed #59604a;border-radius:7px;display:grid;place-items:center;text-align:center;color:#8e9789;font-size:10px;margin:14px 0}.forge-target .anvil{font-size:34px;color:#b29a62;display:block;margin-bottom:8px}.forge-items{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.forge-item{border:1px solid #3b4438;border-radius:5px;background:#222922;padding:8px;text-align:center;cursor:pointer;min-height:67px}.forge-item.chosen{border-color:#d3ac56;background:#302c20}.forge-item .item-icon{font-size:18px}.forge-item small{display:block;font-size:7px;color:#a4ab9e;margin-top:4px}.forge-result{padding:18px;display:flex;flex-direction:column;justify-content:space-between}.forge-result .anvil-big{font-size:64px;text-align:center;color:#af9460;margin:20px}.forge-result .btn{width:100%}.forge-result .cost{font-size:10px;color:#b3b9ab;display:flex;justify-content:space-between;margin:9px 0 15px}.shop-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.shop-card{padding:15px;position:relative;overflow:hidden}.shop-card.featured{border-color:#866c3c;background:linear-gradient(135deg,#332b1e,#1c231d)}.shop-card h3{font:15px var(--display);margin:0 0 6px}.shop-card p{font-size:9px;line-height:1.55;color:#a0a798;margin:0 0 11px}.shop-card .shop-art{position:absolute;right:16px;top:22px;font-size:37px;opacity:.85;text-shadow:0 0 18px #d1ad6b44}.shop-card h3,.shop-card p,.shop-card .shop-pills,.shop-card .btn{position:relative;z-index:1}.shop-pills{display:flex;gap:6px;margin:10px 0}.shop-pills span{font-size:8px;border:1px solid #5b573b;background:#242a21;padding:5px 7px;border-radius:4px;color:#c9bc8f}.shop-card .btn{width:100%}.shop-card .price{float:right;color:#f0d283}.shop-card .limited{position:absolute;right:14px;top:13px;color:#dfb663;font-size:8px;letter-spacing:1px}.pass-card{grid-column:span 2;padding:16px}.pass-track{display:flex;align-items:center;gap:0;margin:14px 0}.pass-step{flex:1;text-align:center;position:relative}.pass-step:before{content:'';position:absolute;left:-50%;top:14px;height:2px;width:100%;background:#444b3e}.pass-step:first-child:before{display:none}.pass-orb{width:28px;height:28px;border-radius:50%;background:#29312a;border:1px solid #515a45;margin:0 auto 7px;display:grid;place-items:center;color:#d0b468;font-size:11px;position:relative}.pass-step.done .pass-orb{background:#525c3d;color:#e5e9d4}.pass-step small{display:block;color:#939a8c;font-size:7px}.daily-card{padding:13px;margin-top:12px;display:flex;align-items:center;gap:12px}.daily-card .daily-icon{font-size:24px;color:var(--gold)}.daily-card div:nth-child(2){flex:1}.daily-card b{font-size:11px}.daily-card small{display:block;color:#9ba294;font-size:9px;margin-top:4px}
