const REGIONS=[
 {name:'Foresta dei Sussurri',biome:'Bosco antico',symbol:'♧',effect:'Benedizione verde',desc:'Radici millenarie e spiriti che custodiscono i sentieri.',enemy:'Lupo delle radici',boss:'Antica Madre',emoji:'🐺',bossEmoji:'🌳',set:'Guardiano del Bosco',color:'#9cbc78'},
 {name:'Paludi Maledette',biome:'Acquitrino',symbol:'♨',effect:'Veleno',desc:'Nebbie venefiche avvolgono rovine dimenticate.',enemy:'Melma famelica',boss:'Idra delle paludi',emoji:'🐸',bossEmoji:'🐍',set:'Velo della Marea',color:'#9bc38c'},
 {name:'Picchi Innevati',biome:'Gelo perenne',symbol:'❄',effect:'Gelo · ATK speed −10%',desc:'La bufera cela antichi titani sotto il ghiaccio.',enemy:'Lince di brina',boss:'Colosso glaciale',emoji:'🐻‍❄️',bossEmoji:'🧊',set:'Cuore di Brina',color:'#9bc5d6'},
 {name:'Cittadella Infernale',biome:'Terre di magma',symbol:'♨',effect:'Calore · Crit +15%',desc:'Fortezze di ossidiana ardono sotto cieli vermigli.',enemy:'Imp di cenere',boss:'Signore delle fiamme',emoji:'👹',bossEmoji:'🔥',set:'Veste del Drago',color:'#e68f64'},
 {name:'Abisso Cosmico',biome:'Oltre il velo',symbol:'✧',effect:'Vuoto · Ricompense +20%',desc:'Il confine tra stelle e incubi si dissolve.',enemy:'Osservatore',boss:'Eclisse eterna',emoji:'👁️',bossEmoji:'🌌',set:'Ordine Astrale',color:'#b29bda'}
];
const SLOTS=['Arma principale','Scudo / secondaria','Elmo','Corazza','Guanti','Stivali'];
const SLOT_ICONS=['⚔','🛡','♜','🥋','♧','👢'];
const RARITIES=['Comune','Non comune','Raro','Epico','Leggendario','Mitico'];
const RARITY_CLASS=['common','uncommon','rare','epic','legendary','mythic'];
const BASE={gold:1200,gems:35,level:1,xp:0,region:0,node:1,kills:0,bosses:0,damage:19,hp:180,inventory:[],gear:{},forgeDust:0,starter:false,passPremium:false,passLevel:3,expeditionAt:0,expeditionRegion:0,lastSave:Date.now(),offlineClaimed:false,questClaimed:false,pity:0,chests:0,upgrades:0,tab:'battle',idle:true};
let game=loadGame(), forgeMode='upgrade', forgeSelected=[], currentView='battle', ticker=null,toastTimer;
function loadGame(){try{return {...BASE,...JSON.parse(localStorage.getItem('emberfall-save')||'{}'),gear:JSON.parse(localStorage.getItem('emberfall-save')||'{}').gear||{},inventory:JSON.parse(localStorage.getItem('emberfall-save')||'{}').inventory||[]}}catch{return {...BASE,gear:{},inventory:[]}}}
function save(){game.lastSave=Date.now();localStorage.setItem('emberfall-save',JSON.stringify(game));updateTop()}
function num(n){return Math.floor(n).toLocaleString('it-IT')}
function currentRegion(){return REGIONS[game.region]||REGIONS[0]}
function attackPower(){return game.damage+Object.values(game.gear).reduce((a,x)=>a+(x?.power||0),0)+Math.floor((game.level-1)*2)}
function showToast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function updateTop(){document.getElementById('gold').textContent=num(game.gold);document.getElementById('gems').textContent=num(game.gems);document.getElementById('topLevel').textContent=game.level;document.getElementById('passLevel').textContent=game.passLevel;document.getElementById('currentRegionSide').textContent=currentRegion().name;let q=Math.min(10,game.kills%11);document.getElementById('questBar').style.width=(q*10)+'%';document.getElementById('questCount').textContent=`${q} / 10`}
function calculateOffline(){let elapsed=Math.max(0,Date.now()-(game.lastSave||Date.now()));let hours=Math.min(24,elapsed/3600000);return {hours,gold:Math.floor(hours*105*(game.starter?1.2:1)),xp:Math.floor(hours*15)}}
function initOffline(){let reward=calculateOffline();let text=document.getElementById('offlineText');text.textContent=reward.hours<.02?'Avventura in corso…':`${reward.hours.toFixed(1)} ore · +${num(reward.gold)} oro`;document.getElementById('claimOffline').disabled=reward.hours<.02}
function go(tab){game.tab=tab;currentView=tab;document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();save()}
function pageHead(kicker,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<div class="subheading">${sub}</div>`:''}</div>${extra}</div>`}
function render(){updateTop();let root=document.getElementById('view');let pages={battle:renderBattle,world:renderWorld,hero:renderHero,forge:renderForge,shop:renderShop};root.innerHTML=(pages[currentView]||renderBattle)();}
function renderBattle(){let r=currentRegion(),boss=game.node===11,enemyHp=Math.max(0,Math.floor((32+game.region*46+game.node*12)*1.6));return `${pageHead('CAPITOLO '+String(game.region+1).padStart(2,'0'), 'La frontiera selvaggia', 'Le tue lame non riposano mai. Continua la tua avventura.', '<span class="badge">● COMBATTIMENTO AUTOMATICO</span>')}
<div class="battle-layout"><div class="battle-stage"><div class="stage-moon"></div><div class="ruin one"></div><div class="ruin two"></div><div class="ground"></div><div class="stage-top"><span class="stage-name">${r.name}</span><div><small>STAGE ${String(game.node).padStart(2,'0')} · ${boss?'BOSS REGIONALE':'ESPLORAZIONE'}</small></div></div><div class="ambient">${r.symbol} &nbsp;${r.effect}</div><div class="combatants"><div class="fighter hero">🧙<div class="health"><span style="width:100%"></span></div><div class="combat-label">IL VIANDANTE</div></div><div class="fighter enemy">${boss?r.bossEmoji:r.emoji}<div class="health"><span id="enemyHealth" style="width:${game.enemyPct??100}%"></span></div><div class="combat-label">${boss?r.boss: r.enemy}</div></div></div><div class="battle-footer"><div class="stage-track"><div class="track-head"><span>PROGRESSO STAGE</span><span>${game.enemyPct===undefined?100:Math.max(0,game.enemyPct)}%</span></div><div class="track"><span style="width:${game.enemyPct??100}%"></span></div></div><button class="btn" data-action="boss">${boss?'⚔ SFIDA BOSS':'PROSSIMO NODO'}</button></div></div>
<div class="combat-side"><div class="enemy-card card"><div class="enemy-head"><div><b>${boss?r.boss:r.enemy}</b><div class="muted">${boss?'BOSS REGIONALE':'Creatura · Liv. '+(game.region*10+game.node)}</div></div><span class="badge">${boss?'BOSS':'NEMICO'}</span></div><div class="boss-art">${boss?r.bossEmoji:r.emoji}</div><div class="boss-stats"><div class="stat-chip"><small>POTENZA EROE</small><b class="green-text">⚔ ${num(attackPower())}</b></div><div class="stat-chip"><small>RICOMPENSA STIMATA</small><b class="gold-text">◉ ${num(32+game.region*35+game.node*8)}</b></div></div></div><div class="battle-stats card"><h3>Riepilogo spedizione</h3><div class="loot-line"><span>Nemici sconfitti</span><b>${num(game.kills)}</b></div><div class="loot-line"><span>Boss abbattuti</span><b>${num(game.bosses)}</b></div><div class="loot-line"><span>Set regionale</span><b>${r.set}</b></div><div class="divider"></div><div class="section-label">ABILITÀ ATTIVE</div><div class="skill-row"><div class="skill" title="Colpo arcano">✧<small>Q</small></div><div class="skill" title="Guardia ferrea">⛨<small>W</small></div><div class="skill" title="Scatto del viandante">➶<small>E</small></div></div><div class="combat-feed" id="combatFeed">${game.idle?'La battaglia continua…':'La battaglia è in pausa.'}</div></div></div></div>
<div class="battle-bottom"><div class="mini-info card"><span class="icon">◉</span><div><small>ORO GUADAGNATO</small><b>${num(game.gold)} <span class="muted">monete</span></b></div></div><div class="mini-info card"><span class="icon">✧</span><div><small>ESPERIENZA</small><b>${num(game.xp)} <span class="muted">XP</span></b></div></div><div class="mini-info card"><span class="icon">♧</span><div><small>ESPLORAZIONE</small><b>${game.region*10+game.node} <span class="muted">/ 55 nodi</span></b></div></div></div>`}

function renderWorld(){let r=currentRegion();return `${pageHead('ATLANTE DI EMBERFALL','Un mondo da scoprire','Cinque terre, cinquanta sentieri e un destino da forgiare.')}
<div class="world-banner"><div class="eyebrow">REGIONE ${String(game.region+1).padStart(2,'0')} · ${r.biome.toUpperCase()}</div><h2>${r.name}</h2><p>${r.desc}</p><div class="world-meta"><span class="badge">${r.symbol} ${r.effect}</span><span class="badge">SET: ${r.set}</span></div></div>
<div class="region-grid">${REGIONS.map((x,i)=>`<div class="region-card card ${i===game.region?'active':''} ${i>game.region?'locked':''}" data-region="${i}" data-symbol="${x.symbol}"><div class="region-num">REGIONE 0${i+1}</div><h3>${x.name}</h3><p>${i>game.region?'Sconfiggi il boss precedente per sbloccare':x.effect}</p><span class="node-count">${i<game.region?'✓ COMPLETATA':i===game.region?`${game.node-1}/11 NODI`:'🔒'}</span></div>`).join('')}</div>
<div class="world-lower"><div class="nodes-card card"><div class="section-label">SENTIERO · ${r.name.toUpperCase()}</div><h2 class="section-title" style="margin-top:5px">Nodi di esplorazione</h2><div class="node-list">${Array.from({length:11},(_,i)=>{let n=i+1,done=game.region<game.region||n<game.node,locked=n>game.node;return `<button class="node ${done?'done':''} ${n===game.node?'current':''} ${n===11?'boss':''} ${locked?'locked':''}" data-node="${n}" ${locked?'disabled':''}><span>${n===11?'♜':done?'✓':n}</span><small>${n===11?'BOSS':done?'LIBERO':n===game.node?'ATTUALE':'—'}</small></button>`}).join('')}</div><div class="divider"></div><div class="section-label">RICOMPENSA DI ZONA</div><div class="loot-line"><span>Completamento regione</span><b>✧ +25 cristalli · Set esclusivo</b></div></div>
<div class="expedition-card card"><div class="section-label">ESPLORAZIONE IDLE</div><h2 class="section-title" style="margin-top:5px">Spedizione nella regione</h2><div class="expedition-art"><span>♧</span><span>⟡</span><span>♜</span></div><p>Invia un esploratore in cerca di santuari, forzieri e dungeon temporanei. Tornerà con tesori anche mentre sei offline.</p><div class="expedition-details"><span>Durata <b>2 ore</b></span><span>Possibili gemme <b>✧ 2–8</b></span></div><button class="btn secondary" data-action="expedition">${game.expeditionAt>Date.now()?'SPEDIZIONE IN CORSO':'INVIA ESPLORATORE'}</button></div></div>`}
function itemName(item){return item?item.name:'Nessun oggetto'}
function renderHero(){let gear=Object.keys(game.gear).length, slots=SLOTS.map((s,i)=>{let it=game.gear[i];return `<div class="gear-slot" data-slot="${i}"><div>${SLOT_ICONS[i]}</div><small>${s.toUpperCase()}</small><b class="${it?'rarity-'+RARITY_CLASS[it.rarity]:''}">${it?it.name:'Vuoto · scegli equip'}</b></div>`}).join('');let inv=game.inventory.length?game.inventory.slice(0,18).map((it,i)=>`<div class="inventory-item ${it.selected?'selected':''}" data-item="${it.id}"><div class="item-icon ${'rarity-'+RARITY_CLASS[it.rarity]}">${SLOT_ICONS[it.slot]}</div><small class="rarity-${RARITY_CLASS[it.rarity]}">${it.name}</small></div>`).join(''):'<div class="muted" style="grid-column:span 6;font-size:10px;padding:12px">Ancora nessun oggetto. Avanza nella battaglia o apri un forziere.</div>';
return `${pageHead('IL VIANDANTE','Il tuo eroe','Equipaggia reliquie, affina le tue abilità e preparati alla prossima sfida.')}
<div class="hero-grid"><div class="hero-portrait card"><div class="hero-level">LIVELLO ${game.level}</div>🧙<div class="hero-xp"><div class="section-label">ESPERIENZA · ${game.xp%100} / 100 XP</div><div><span style="width:${game.xp%100}%"></span></div></div></div><div class="hero-summary card"><div class="eyebrow">CLASSE · CUSTODE DEL CREPUSCOLO</div><h2>Arin, il viandante</h2><p>Un guerriero errante legato alla magia primordiale.</p><div class="stats-grid"><div class="stat-chip"><small>ATTACCO</small><b class="green-text">⚔ ${num(attackPower())}</b></div><div class="stat-chip"><small>VITALITÀ</small><b>♥ ${num(game.hp+game.level*8)}</b></div><div class="stat-chip"><small>CRITICO</small><b class="gold-text">✦ 12%</b></div><div class="stat-chip"><small>ORO BONUS</small><b class="gold-text">+${game.starter?20:0}%</b></div></div><div class="divider"></div><span class="badge">ABILITÀ SBLOCCATE · 3/8</span></div></div>
<div class="gear-panel card"><div style="display:flex;justify-content:space-between;align-items:center"><h2 class="section-title">Equipaggiamento</h2><span class="section-label">${gear} / 6 SLOT · SET ${game.gear.length>=4?'ATTIVO':''}</span></div><div class="gear-slots">${slots}</div><div class="divider"></div><div class="section-label">BONUS SET · ${currentRegion().set.toUpperCase()}</div><div class="loot-line"><span>2 pezzi equipaggiati</span><b class="${gear>=2?'green-text':'muted'}">${gear>=2?'+15% ATK':'0 / 2'}</b></div><div class="loot-line"><span>4 pezzi equipaggiati</span><b class="${gear>=4?'green-text':'muted'}">${gear>=4?'+30% danni elementali':'0 / 4'}</b></div></div>
<div class="inventory-card card"><div style="display:flex;justify-content:space-between"><h2 class="section-title">Inventario</h2><span class="section-label">${game.inventory.length} / ${game.inventoryCapacity||30}</span></div><div class="inventory-grid">${inv}</div></div>`}
function renderForge(){let items=game.inventory.map(it=>`<div class="forge-item ${forgeSelected.includes(it.id)?'chosen':''}" data-forge-item="${it.id}"><div class="item-icon rarity-${RARITY_CLASS[it.rarity]}">${SLOT_ICONS[it.slot]}</div><small class="rarity-${RARITY_CLASS[it.rarity]}">${it.name}</small></div>`).join('');let title=forgeMode==='upgrade'?'Potenziamento':forgeMode==='fuse'?'Fusione':'Smantellamento';return `${pageHead('ARTIGIANATO','La Forgia Antica','Rafforza il tuo equipaggiamento o trasforma i doppioni in Polvere Arcana.')}
<div class="forge-grid"><div class="forge-box card"><h2>${title}</h2><p>${forgeMode==='upgrade'?'Spendi oro e polvere per aumentare la potenza di un oggetto.':'Scegli oggetti dall’inventario per procedere.'}</p><div class="forge-options"><button data-forge-mode="upgrade" class="${forgeMode==='upgrade'?'active':''}">POTENZIA</button><button data-forge-mode="fuse" class="${forgeMode==='fuse'?'active':''}">FONDI 3</button><button data-forge-mode="dust" class="${forgeMode==='dust'?'active':''}">SMANTELLA</button></div><div class="forge-target"><div><span class="anvil">⚒</span>${forgeSelected.length?`${forgeSelected.length} oggetti selezionati`:'Seleziona oggetti dall’inventario qui sotto'}</div></div><div class="forge-items">${items||'<div class="muted" style="grid-column:span 4;font-size:10px">Nessun oggetto da lavorare: combatti per trovare loot.</div>'}</div></div><div class="forge-result card"><div><div class="section-label">FONDERIA · LIVELLO 1</div><div class="anvil-big">⚒</div><h2 class="section-title" style="text-align:center">${forgeMode==='fuse'?'Fusione equipaggiamento':forgeMode==='dust'?'Polvere Arcana':'Migliora il tuo gear'}</h2><p class="muted" style="font-size:10px;line-height:1.6;text-align:center">${forgeMode==='fuse'?'Combina 3 oggetti dello stesso slot e rarità per ottenerne uno di grado superiore.':forgeMode==='dust'?'Smantella gli oggetti selezionati per ottenere polvere arcana.':'Ogni potenziamento aumenta permanentemente l’attacco del tuo oggetto.'}</p></div><div><div class="cost"><span>Costo richiesto</span><b class="gold-text">${forgeMode==='dust'?'—':forgeMode==='fuse'?'3 oggetti':'◉ '+num(100+game.upgrades*40)}</b></div><button class="btn" data-action="forge">${forgeMode==='dust'?'SMANTELLA SELEZIONE':forgeMode==='fuse'?'FONDI OGGETTI':'POTENZIA EQUIP'}</button><div class="loot-line"><span>Polvere Arcana</span><b class="purple-text">✧ ${num(game.forgeDust)}</b></div></div></div></div>`}

function renderShop(){return `${pageHead('EMPORIO DEL VIANDANTE','Il Mercato del Crepuscolo','Scambia cristalli, ritira ricompense e preparati a nuove avventure.')}
<div class="shop-grid"><div class="shop-card featured card"><span class="limited">✦ OFFERTA UNICA</span><div class="shop-art">⚔</div><h3>Pacchetto Principiante</h3><p>Il kit perfetto per partire: un’arma Epica, cristalli e un bonus permanente all’oro.</p><div class="shop-pills"><span>⚔ Arma Epica</span><span>✧ 150 cristalli</span><span>◉ +20% oro</span></div><button class="btn" data-buy="starter">${game.starter?'ACQUISTATO':'ACQUISTA · €2,99'}</button></div><div class="shop-card card"><div class="shop-art">♜</div><h3>Forziere evocazione</h3><p>Un equipaggiamento casuale. Ogni 10 aperture garantisce almeno un oggetto Leggendario.</p><div class="shop-pills"><span>✦ Raro 55%</span><span>✦ Epico 35%</span><span>★ Leg. 9%</span><span>✧ Mit. 1%</span></div><button class="btn secondary" data-buy="chest">APRI FORZIERE · 80 ✧ <span class="price">${game.pity}/10</span></button></div>
<div class="shop-card card"><div class="shop-art">⛨</div><h3>Pass Avventura</h3><p>Ricompense gratuite per ogni regione. Sblocca il percorso Premium per tesori esclusivi.</p><div class="shop-pills"><span>GRATUITO · DISPONIBILE</span><span>PREMIUM · +RICOMPENSE</span></div><button class="btn secondary" data-buy="pass">${game.passPremium?'PASS PREMIUM ATTIVO':'SBLOCCA PREMIUM · 300 ✧'}</button></div><div class="shop-card card"><div class="shop-art">◷</div><h3>Reliquie di convenienza</h3><p>Più spazio, più ricompense offline e una vita senza interruzioni.</p><div class="shop-pills"><span>Inventario +20</span><span>Offline ×2</span><span>Niente pubblicità</span></div><button class="btn secondary" data-buy="convenience">POTENZIAMENTO · €1,99</button></div>
<div class="pass-card card"><div class="section-label">STAGIONE I · IL RICHIAMO DEL CREPUSCOLO</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:5px"><h2 class="section-title">Pass Avventura <span class="gold-text">Liv. ${game.passLevel}</span></h2><span class="section-label">${game.passPremium?'PREMIUM SBLOCCATO':'PERCORSO GRATUITO'}</span></div><div class="pass-track">${[1,2,3,4,5,6].map((n)=>`<div class="pass-step ${n<=game.passLevel?'done':''}"><div class="pass-orb">${n<=game.passLevel?'✓':n}</div><small>${n%2?'✧ Cristalli':'◉ Oro'}</small></div>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center"><span class="muted" style="font-size:9px">Esplora nuove regioni per avanzare nel pass.</span><button class="btn small secondary" data-action="passReward">RISCATTA RICOMPENSA</button></div></div></div>
