function makeItem(slot,rarity){let names=[['Lama del sottobosco','Arco di linfa','Spada di radice','Zanna selvaggia'],['Scudo di corteccia','Falcetto lunare','Tomo antico'],['Corona di muschio','Cappuccio errante','Elmo di guardia'],['Corazza di foglie','Mantello druidico','Tunica del viandante'],['Guanti del cacciatore','Bracciali runici'],['Stivali silvani','Passi del vento']];let regionSet=currentRegion().set;let n=names[slot][Math.floor(Math.random()*names[slot].length)];let prefix=['','Verdeggiante','Antico','Eroico','Leggendario','Mitico'][rarity];let power=[3,6,10,18,29,45][rarity]+game.region*4;return {id:Date.now()+Math.random(),slot,rarity,name:prefix+' '+n,power,set:regionSet}}
function rollLoot(forceRarity=null){let roll=Math.random(),r=forceRarity;if(r===null){if(game.pity>=9)r=4;else r=roll<.01?5:roll<.10?4:roll<.40?3:roll<.7?2:roll<.9?1:0}let item=makeItem(Math.floor(Math.random()*6),r);game.inventory.unshift(item);return item}
function grantKill(){let base=32+game.region*35+game.node*8;game.gold+=Math.floor(base*(game.starter?1.2:1));game.xp+=12;game.kills++;game.enemyPct=100;if(game.xp>=100){game.xp-=100;game.level++;game.damage+=2;showToast(`Livello ${game.level} raggiunto! +2 attacco`)}if(Math.random()<.14){let item=rollLoot();showToast(`Bottino: ${item.name} (${RARITIES[item.rarity]})`)}if(game.kills%10===0&&!game.questClaimed){game.gems+=5;game.questClaimed=true;showToast('Missione completata! +5 cristalli')}save();render()}
function advanceNode(boss=false){if(game.node===11){if(!boss){showToast('Affronta il Boss regionale!');return}game.bosses++;game.gems+=25;game.node=1;if(game.region<REGIONS.length-1){game.region++;showToast(`Boss sconfitto! ${currentRegion().name} sbloccata · +25 ✧`)}else {game.region=0;showToast('L’Abisso è stato domato! +25 ✧')}}else{game.node++;showToast(`Nodo ${game.node} raggiunto`)}save();render()}
function actForge(){if(forgeMode==='upgrade'){if(game.gold<100+game.upgrades*40){showToast('Oro insufficiente');return}game.gold-=100+game.upgrades*40;game.upgrades++;game.damage+=3;showToast('Equipaggiamento potenziato · +3 attacco')}else if(forgeMode==='dust'){if(!forgeSelected.length){showToast('Seleziona almeno un oggetto');return}let n=0;game.inventory=game.inventory.filter(it=>{if(forgeSelected.includes(it.id)){n++;return false}return true});game.forgeDust+=n*5;forgeSelected=[];showToast(`Smantellati ${n} oggetti · +${n*5} polvere`)}else{if(forgeSelected.length!==3){showToast('Seleziona esattamente 3 oggetti');return}let selected=game.inventory.filter(it=>forgeSelected.includes(it.id));if(selected.length!==3||!selected.every(x=>x.slot===selected[0].slot&&x.rarity===selected[0].rarity)){showToast('Gli oggetti devono avere stesso slot e rarità');return}let rar=Math.min(5,selected[0].rarity+1),slot=selected[0].slot;game.inventory=game.inventory.filter(it=>!forgeSelected.includes(it.id));let item=makeItem(slot,rar);game.inventory.unshift(item);forgeSelected=[];showToast(`Fusione riuscita! ${item.name}`)}save();render()}
function equipItem(id){let idx=game.inventory.findIndex(x=>String(x.id)===String(id));if(idx<0)return;let item=game.inventory.splice(idx,1)[0];let old=game.gear[item.slot];if(old)game.inventory.push(old);game.gear[item.slot]=item;showToast(`${item.name} equipaggiato`);save();render()}
function modal(title,text,yesLabel,action){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>${title}</h2><p>${text}</p><div class="modal-actions"><button class="btn ghost" data-action="closeModal">ANNULLA</button><button class="btn" data-confirm="${action}">${yesLabel}</button></div></div></div>`}
function buy(type){if(type==='starter'){if(game.starter){showToast('Hai già acquistato il pacchetto!');return}modal('Pacchetto Principiante','Acquisto simulato · €2,99. Riceverai un’arma Epica garantita, 150 cristalli e +20% oro permanente.','CONFERMA ACQUISTO','starter')}if(type==='convenience')modal('Reliquie di convenienza','Acquisto simulato · €1,99. Aumenta lo spazio inventario a 50 slot e raddoppia i ricavi offline.','CONFERMA · €1,99','convenience');if(type==='chest'){if(game.gems<80){showToast('Cristalli insufficienti');return}game.gems-=80;game.chests++;let item=rollLoot();game.pity=item.rarity>=4?0:game.pity+1;save();render();modal('Forziere aperto!',`${item.name} · ${RARITIES[item.rarity]} · +${item.power} ATK. Pity: ${game.pity}/10 aperture.`, 'FANTASTICO','closeModal')}if(type==='pass'){if(game.passPremium){showToast('Pass già attivo');return}if(game.gems<300){showToast('Servono 300 cristalli');return}game.gems-=300;game.passPremium=true;showToast('Pass Premium sbloccato!');save();render()}}

