const REGIONS=[
 {name:'Foresta dei Sussurri',biome:'Bosco antico',symbol:'♧',effect:'Benedizione verde',desc:'Radici millenarie e spiriti che custodiscono i sentieri.',enemy:'Lupo delle radici',boss:'Antica Madre',emoji:'🐺',bossEmoji:'🌳',set:'Guardiano del Bosco'},
 {name:'Paludi Maledette',biome:'Acquitrino',symbol:'♨',effect:'Veleno',desc:'Nebbie venefiche avvolgono rovine dimenticate.',enemy:'Melma famelica',boss:'Idra delle paludi',emoji:'🐸',bossEmoji:'🐍',set:'Velo della Marea'},
 {name:'Picchi Innevati',biome:'Gelo perenne',symbol:'❄',effect:'Gelo · ATK speed −10%',desc:'La bufera cela antichi titani sotto il ghiaccio.',enemy:'Lince di brina',boss:'Colosso glaciale',emoji:'🐻‍❄️',bossEmoji:'🧊',set:'Cuore di Brina'},
 {name:'Cittadella Infernale',biome:'Terre di magma',symbol:'♨',effect:'Calore · Crit +15%',desc:'Fortezze di ossidiana ardono sotto cieli vermigli.',enemy:'Imp di cenere',boss:'Signore delle fiamme',emoji:'👹',bossEmoji:'🔥',set:'Veste del Drago'},
 {name:'Abisso Cosmico',biome:'Oltre il velo',symbol:'✧',effect:'Vuoto · Ricompense +20%',desc:'Il confine tra stelle e incubi si dissolve.',enemy:'Osservatore',boss:'Eclisse eterna',emoji:'👁️',bossEmoji:'🌌',set:'Ordine Astrale'}
];
const SLOTS=['Arma principale','Scudo / secondaria','Elmo','Corazza','Guanti','Stivali'], SLOT_ICONS=['⚔','🛡','♜','🥋','♧','👢'];
const RARITIES=['Comune','Non comune','Raro','Epico','Leggendario','Mitico'], RARITY_CLASS=['common','uncommon','rare','epic','legendary','mythic'];
const BASE={gold:1200,gems:35,level:1,xp:0,region:0,node:1,kills:0,bosses:0,damage:19,hp:180,inventory:[],gear:{},forgeDust:0,starter:false,passPremium:false,passLevel:3,expeditionAt:0,expeditionRegion:0,lastSave:Date.now(),offlineAt:Date.now(),questClaimed:false,pity:0,chests:0,upgrades:0,tab:'battle',idle:true};
let game=loadGame(),forgeMode='upgrade',forgeSelected=[],currentView=game.tab||'battle',toastTimer;
function loadGame(){try{const d=JSON.parse(localStorage.getItem('emberfall-save')||'{}');return {...BASE,...d,gear:d.gear||{},inventory:d.inventory||[],offlineAt:d.offlineAt||Date.now()}}catch{return {...BASE,gear:{},inventory:[]}}}
function save(){game.lastSave=Date.now();localStorage.setItem('emberfall-save',JSON.stringify(game));updateTop()}
function num(n){return Math.floor(n).toLocaleString('it-IT')} function currentRegion(){return REGIONS[game.region]||REGIONS[0]}
function attackPower(){return game.damage+Object.values(game.gear).reduce((a,x)=>a+(x?.power||0),0)+Math.floor((game.level-1)*2)}
function showToast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function updateTop(){document.getElementById('gold').textContent=num(game.gold);document.getElementById('gems').textContent=num(game.gems);document.getElementById('topLevel').textContent=game.level;document.getElementById('passLevel').textContent=game.passLevel;document.getElementById('currentRegionSide').textContent=currentRegion().name;let q=game.kills%10;document.getElementById('questBar').style.width=(q*10)+'%';document.getElementById('questCount').textContent=`${q} / 10`}
function calculateOffline(){let hours=Math.min(24,Math.max(0,Date.now()-(game.offlineAt||Date.now()))/3600000);return {hours,gold:Math.floor(hours*105*(game.offlineBoost?2:1)*(game.starter?1.2:1)),xp:Math.floor(hours*15)}}
function initOffline(){let reward=calculateOffline();document.getElementById('offlineText').textContent=reward.hours<.02?'Avventura in corso…':`${reward.hours.toFixed(1)} ore · +${num(reward.gold)} oro`;document.getElementById('claimOffline').disabled=reward.hours<.02}
function go(tab){currentView=tab;game.tab=tab;document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();save()}
function pageHead(kicker,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<div class="subheading">${sub}</div>`:''}</div>${extra}</div>`}
