Riepilogo spedizione</h3><div class="loot-line"><span>Nemici sconfitti</span><b>${num(game.kills)}</b></div><div class="loot-line"><span>Boss abbattuti</span><b>${num(game.bosses)}</b></div><div class="loot-line"><span>Set regionale</span><b>${r.set}</b></div><div class="divider"></div><div class="section-label">ABILITÀ ATTIVE</div><div class="skill-row"><div class="skill">✧<small>Q</small></div><div class="skill">⛨<small>W</small></div><div class="skill">➶<small>E</small></div></div><div class="combat-feed" id="combatFeed">${game.idle?'La battaglia continua…':'La battaglia è in pausa.'}</div></div></div></div><div class="battle-bottom"><div class="mini-info card"><span class="icon">◉</span><div><small>ORO GUADAGNATO</small><b>${num(game.gold)} <span class="muted">monete</span></b></div></div><div class="mini-info card"><span class="icon">✧</span><div><small>ESPERIENZA</small><b>${num(game.xp)} <span class="muted">XP</span></b></div></div><div class="mini-info card"><span class="icon">♧</span><div><small>ESPLORAZIONE</small><b>${game.region*11+game.node} <span class="muted">/ 55 nodi</span></b></div></div></div>`}
