// Emberfall — ricostruzione completa delle interazioni
const REGIONS=[
 {name:'Foresta dei Sussurri',biome:'Bosco antico',symbol:'♧',effect:'Benedizione verde',desc:'Radici millenarie e spiriti che custodiscono i sentieri.',enemy:'Lupo delle radici',boss:'Antica Madre',emoji:'🐺',bossEmoji:'🌳',set:'Guardiano del Bosco'},
 {name:'Paludi Maledette',biome:'Acquitrino',symbol:'♨',effect:'Veleno',desc:'Nebbie venefiche avvolgono rovine dimenticate.',enemy:'Melma famelica',boss:'Idra delle paludi',emoji:'🐸',bossEmoji:'🐍',set:'Velo della Marea'},
 {name:'Picchi Innevati',biome:'Gelo perenne',symbol:'❄',effect:'Gelo · ATK speed −10%',desc:'La bufera cela antichi titani sotto il ghiaccio.',enemy:'Lince di brina',boss:'Colosso glaciale',emoji:'🐻‍❄️',bossEmoji:'🧊',set:'Cuore di Brina'},
 {name:'Cittadella Infernale',biome:'Terre di magma',symbol:'♨',effect:'Calore · Crit +15%',desc:'Fortezze di ossidiana ardono sotto cieli vermigli.',enemy:'Imp di cenere',boss:'Signore delle fiamme',emoji:'👹',bossEmoji:'🔥',set:'Veste del Drago'},
 {name:'Abisso Cosmico',biome:'Oltre il velo',symbol:'✧',effect:'Vuoto · Ricompense +20%',desc:'Il confine tra stelle e incubi si dissolve.',enemy:'Osservatore',boss:'Eclisse eterna',emoji:'👁️',bossEmoji:'🌌',set:'Ordine Astrale'}
];
const SLOTS=['Arma principale','Scudo / secondaria','Elmo','Corazza','Guanti','Stivali'], SLOT_ICONS=['⚔','🛡','♜','🥋','♧','👢'];
const RARITIES=['Comune','Non comune','Raro','Epico','Leggendario','Mitico'], RARITY_CLASS=['common','uncommon','rare','epic','legendary','mythic'];
const BASE={gold:1200,gems:35,level:1,xp:0,region:0,node:1,kills:0,bosses:0,damage:19,hp:180,inventory:[],gear:{},forgeDust:0,starter:false,passPremium:false,passLevel:3,expeditionAt:0,expeditionRegion:0,lastSave:Date.now(),offlineAt:Date.now(),questClaimed:false,pity:0,chests:0,upgrades:0,tab:'battle',idle:true,enemyPct:100,inventoryCapacity:30};
let game=loadGame(),forgeMode='upgrade',forgeSelected=[],currentView=game.tab||'battle',toastTimer;

function loadGame(){try{const d=JSON.parse(localStorage.getItem('emberfall-save')||'{}');return {...BASE,...d,gear:d.gear||{},inventory:d.inventory||[],offlineAt:d.offlineAt||Date.now()}}catch(e){return {...BASE,gear:{},inventory:[]}}}
function save(){game.lastSave=Date.now();localStorage.setItem('emberfall-save',JSON.stringify(game));updateTop()}
function num(n){return Math.floor(n).toLocaleString('it-IT')}
function currentRegion(){return REGIONS[game.region]||REGIONS[0]}
function attackPower(){return game.damage+Object.values(game.gear).reduce((a,x)=>a+(x?.power||0),0)+Math.floor((game.level-1)*2)}
function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function updateTop(){document.getElementById('gold').textContent=num(game.gold);document.getElementById('gems').textContent=num(game.gems);document.getElementById('topLevel').textContent=game.level;document.getElementById('passLevel').textContent=game.passLevel;document.getElementById('currentRegionSide').textContent=currentRegion().name;const q=game.kills%10;document.getElementById('questBar').style.width=(q*10)+'%';document.getElementById('questCount').textContent=`${q} / 10`}
function calculateOffline(){const hours=Math.min(24,Math.max(0,(Date.now()-game.offlineAt)/3600000));return {hours,gold:Math.floor(hours*105*(game.offlineBoost?2:1)*(game.starter?1.2:1)),xp:Math.floor(hours*15)}}
function initOffline(){const reward=calculateOffline();document.getElementById('offlineText').textContent=reward.hours<.02?'Avventura in corso…':`${reward.hours.toFixed(1)} ore · +${num(reward.gold)} oro`;document.getElementById('claimOffline').disabled=reward.hours<.02}
function go(tab){currentView=tab;game.tab=tab;document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();save()}
function pageHead(kicker,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<div class="subheading">${sub}</div>`:''}</div>${extra}</div>`}

function render(){updateTop();initOffline();const root=document.getElementById('view');const pages={battle:renderBattle,world:renderWorld,hero:renderHero,forge:renderForge,shop:renderShop};root.innerHTML=(pages[currentView]||renderBattle)()}

function renderBattle(){const r=currentRegion(),boss=game.node===11,pct=game.enemyPct??100;return `${pageHead('CAPITOLO '+String(game.region+1).padStart(2,'0'),'La frontiera selvaggia','Le tue lame non riposano mai. Continua la tua avventura.','<span class="badge">● COMBATTIMENTO AUTOMATICO</span>')}<div class="battle-layout"><div class="battle-stage"><div class="stage-moon"></div><div class="ruin one"></div><div class="ruin two"></div><div class="ground"></div><div class="stage-top"><span class="stage-name">${r.name}</span><small>STAGE ${String(game.node).padStart(2,'0')} · ${boss?'BOSS REGIONALE':'ESPLORAZIONE'}</small></div><div class="ambient">${r.symbol} ${r.effect}</div><div class="combatants"><div class="fighter hero">🧙<div class="health"><span style="width:100%"></span></div><div class="combat-label">IL VIANDANTE</div></div><div class="fighter enemy">${boss?r.bossEmoji:r.emoji}<div class="health"><span style="width:${pct}%"></span></div><div class="combat-label">${boss?r.boss:r.enemy}</div></div></div><div class="battle-footer"><div class="stage-track"><div class="track-head"><span>PROGRESSO STAGE</span><span>${pct}%</span></div><div class="track"><span style="width:${pct}%"></span></div></div><button class="btn" data-action="next">${boss?'⚔ SFIDA BOSS':'PROSSIMO NODO'}</button></div></div><div class="combat-side"><div class="enemy-card card"><div class="enemy-head"><div><b>${boss?r.boss:r.enemy}</b><div class="muted">Livello ${game.region*10+game.node}</div></div><span class="badge">${boss?'BOSS':'NEMICO'}</span></div><div class="boss-art">${boss?r.bossEmoji:r.emoji}</div><div class="boss-stats"><div class="stat-chip"><small>POTENZA EROE</small><b class="green-text">⚔ ${num(attackPower())}</b></div><div class="stat-chip"><small>RICOMPENSA</small><b class="gold-text">◉ ${num(32+game.region*35+game.node*8)}</b></div></div></div><div class="battle-stats card"><h3>Riepilogo spedizione</h3><div class="loot-line"><span>Nemici sconfitti</span><b>${num(game.kills)}</b></div><div class="loot-line"><span>Boss abbattuti</span><b>${num(game.bosses)}</b></div><div class="divider"></div><div class="combat-feed">${game.idle?'La battaglia continua…':'La battaglia è in pausa.'}</div></div></div></div><div class="battle-bottom"><div class="mini-info card"><span class="icon">◉</span><div><small>ORO</small><b>${num(game.gold)}</b></div></div><div class="mini-info card"><span class="icon">✧</span><div><small>ESPERIENZA</small><b>${num(game.xp)} XP</b></div></div><div class="mini-info card"><span class="icon">♧</span><div><small>ESPLORAZIONE</small><b>${game.region*11+game.node}/55</b></div></div></div>`}

function renderWorld(){const r=currentRegion();return `${pageHead('ATLANTE','Un mondo da scoprire','Cinque terre, cinquanta sentieri.')}<div class="world-banner"><div class="eyebrow">REGIONE ${game.region+1} · ${r.biome.toUpperCase()}</div><h2>${r.name}</h2><p>${r.desc}</p><div class="world-meta"><span class="badge">${r.symbol} ${r.effect}</span><span class="badge">SET: ${r.set}</span></div></div><div class="region-grid">${REGIONS.map((x,i)=>`<div class="region-card card ${i===game.region?'active':''} ${i>game.region?'locked':''}" data-region="${i}" data-symbol="${x.symbol}"><div class="region-num">REGIONE 0${i+1}</div><h3>${x.name}</h3><p>${i>game.region?'Sconfiggi il boss precedente':'Esplora il sentiero'}</p><span class="node-count">${i<game.region?'✓':i===game.region?`${game.node-1}/11`:'🔒'}</span></div>`).join('')}</div><div class="world-lower"><div class="nodes-card card"><div class="section-label">Nodi di esplorazione</div><div class="node-list">${Array.from({length:11},(_,i)=>{const n=i+1,done=n<game.node,locked=n>game.node;return `<button class="node ${done?'done':''} ${n===game.node?'current':''}" data-node="${n}" ${locked?'disabled':''}><span>${n===11?'♜':done?'✓':n}</span><small>${n===11?'BOSS':'NODO'}</small></button>`}).join('')}</div></div><div class="expedition-card card"><div class="section-label">ESPLORAZIONE IDLE</div><h2 class="section-title">Spedizione nella regione</h2><div class="expedition-details"><span>Durata <b>2 min (demo)</b></span></div><button class="btn secondary" data-action="expedition">${game.expeditionAt>Date.now()?'SPEDIZIONE IN CORSO':'INVIA ESPLORATORE'}</button></div></div>`}

function renderHero(){const gear=Object.keys(game.gear).length,slots=SLOTS.map((s,i)=>{const it=game.gear[i];return `<div class="gear-slot" data-slot="${i}"><div>${SLOT_ICONS[i]}</div><small>${s.toUpperCase()}</small><b class="${it?'rarity-'+RARITY_CLASS[it.rarity]:''}">${it?it.name:'Vuoto'}</b></div>`}).join(''),inv=game.inventory.length?game.inventory.map(it=>`<div class="inventory-item" data-item="${it.id}"><div class="item-icon rarity-${RARITY_CLASS[it.rarity]}">${SLOT_ICONS[it.slot]}</div><small class="rarity-${RARITY_CLASS[it.rarity]}">${it.name}</small></div>`).join(''):'<div class="muted">Nessun oggetto. Combatti per trovare loot.</div>';return `${pageHead('IL VIANDANTE','Il tuo eroe','Equipaggia reliquie e preparati alla sfida.')}<div class="hero-grid"><div class="hero-portrait card"><div class="hero-level">LIVELLO ${game.level}</div>🧙<div class="hero-xp"><span style="width:${game.xp%100}%"></span></div></div><div class="hero-summary card"><h2>Arin, il viandante</h2><div class="stats-grid"><div class="stat-chip"><small>ATTACCO</small><b class="green-text">⚔ ${num(attackPower())}</b></div><div class="stat-chip"><small>VITALITÀ</small><b>♥ ${game.hp+game.level*8}</b></div><div class="stat-chip"><small>CRITICO</small><b>✦ 12%</b></div></div></div></div><div class="gear-panel card"><h2 class="section-title">Equipaggiamento · ${gear}/6</h2><div class="gear-slots">${slots}</div></div><div class="inventory-card card"><h2 class="section-title">Inventario</h2><div class="inventory-grid">${inv}</div></div>`}

function renderForge(){const items=game.inventory.map(it=>`<div class="forge-item ${forgeSelected.includes(it.id)?'chosen':''}" data-forge-item="${it.id}"><div class="item-icon rarity-${RARITY_CLASS[it.rarity]}">${SLOT_ICONS[it.slot]}</div><small class="rarity-${RARITY_CLASS[it.rarity]}">${it.name}</small></div>`).join(''),title=forgeMode==='upgrade'?'Potenziamento':forgeMode==='fuse'?'Fusione':'Smantellamento';return `${pageHead('ARTIGIANATO','La Forgia Antica','Rafforza l’equipaggiamento o trasforma i doppioni.')}<div class="forge-grid"><div class="forge-box card"><h2>${title}</h2><div class="forge-options"><button data-forge-mode="upgrade" class="${forgeMode==='upgrade'?'active':''}">POTENZIA</button><button data-forge-mode="fuse" class="${forgeMode==='fuse'?'active':''}">FONDI 3</button><button data-forge-mode="dust" class="${forgeMode==='dust'?'active':''}">SMANTELLA</button></div><div class="forge-target">${forgeSelected.length?forgeSelected.length+' oggetti selezionati':'Seleziona oggetti dall’inventario'}</div><div class="forge-items">${items||'<div class="muted">Nessun oggetto</div>'}</div></div><div class="forge-result card"><div class="anvil-big">⚒</div><button class="btn" data-action="forge">${forgeMode==='dust'?'SMANTELLA':forgeMode==='fuse'?'FONDI OGGETTI':'POTENZIA'}</button><div class="loot-line"><span>Polvere Arcana</span><b>✧ ${num(game.forgeDust)}</b></div></div></div>`}

function renderShop(){return `${pageHead('PROVVIGIONI','Negozio & offerte','Acquisti simulati: nessun pagamento reale.')}<div class="shop-grid"><div class="card shop-card"><h2>Starter Pack</h2><p>Equippaggio raro + 500 oro + 50 cristalli</p><button class="btn ${game.starter?'':'secondary'}" data-shop="starter">${game.starter?'ACQUISTATO':'€ 4,99 · SIMULATO'}</button></div><div class="card shop-card"><h2>Gacha Celeste</h2><p>Pity garantita al 10° tentativo</p><div class="loot-line"><span>Pity</span><b>${game.pity}/10</b></div><button class="btn secondary" data-shop="gacha">APERTO · 100 ✧</button></div><div class="card shop-card"><h2>Boost Offline</h2><p>Doppie ricompense offline</p><button class="btn secondary" data-shop="boost">ATTIVA · 250 ✧</button></div></div>`}

function makeItem(slot){const roll=Math.random(),rarity=roll>.94?4:roll>.78?3:roll>.58?2:roll>.35?1:0,power=(5+game.region*3+slot*2)*(rarity+1);return {id:'i'+Date.now()+Math.random().toString(16).slice(2),slot,name:`${RARITIES[rarity]} ${SLOTS[slot]}`,rarity,power,level:1}}
function addLoot(){if(game.inventory.length>=game.inventoryCapacity){showToast('Inventario pieno');return}if(Math.random()<.72){const it=makeItem(Math.floor(Math.random()*6));game.inventory.push(it);showToast('Ottenuto: '+it.name)}}
function addXp(amount){game.xp+=amount;if(game.xp>=game.level*100){game.xp-=game.level*100;game.level++;showToast('Livello '+game.level+' raggiunto!')}}
function combatTick(){if(!game.idle)return;game.enemyPct-=Math.max(4,attackPower()/3);if(game.enemyPct<=0){game.enemyPct=100;game.kills++;const boss=game.node===11;if(boss){game.bosses++;game.gems+=25;if(game.region<4){game.region++;game.node=1}else{game.node=11}showToast('Boss sconfitto!')}else{game.node++;}const gold=(32+game.region*35+game.node*8)*(game.starter?1.2:1);game.gold+=gold;addXp(18+game.node*2);addLoot();if(game.kills>0&&game.kills%10===0&&!game.questClaimed){game.gems+=5;game.questClaimed=true;showToast('Missione giornaliera completata')}save();if(currentView==='battle')render()}}

function startExpedition(){if(game.expeditionAt>Date.now())return showToast('Spedizione già in corso');game.expeditionAt=Date.now()+120000;game.expeditionRegion=game.region;showToast('Esploratore inviato');save();render()}
function claimExpedition(){if(game.expeditionAt>0&&game.expeditionAt<=Date.now()){const gems=2+Math.floor(Math.random()*7);game.gems+=gems;game.gold+=300;game.expeditionAt=0;showToast('Spedizione completata: +'+gems+' cristalli');save();render()}}
function forgeAction(){if(forgeMode==='upgrade'){if(!forgeSelected.length)return showToast('Seleziona un oggetto');const it=game.inventory.find(x=>x.id===forgeSelected[0]);if(!it)return;const cost=100+game.upgrades*40;if(game.gold<cost)return showToast('Oro insufficiente');game.gold-=cost;it.power+=8+it.level*2;it.level++;game.upgrades++;showToast('Oggetto potenziato')}else if(forgeMode==='dust'){if(!forgeSelected.length)return showToast('Seleziona oggetti');let dust=0;for(const id of forgeSelected){const i=game.inventory.findIndex(x=>x.id===id);if(i>=0){const it=game.inventory[i];dust+=3+it.rarity*2;game.inventory.splice(i,1)}}game.forgeDust+=dust;showToast('Ottenuta Polvere Arcana: '+dust)}else{if(forgeSelected.length!==3)return showToast('Seleziona esattamente 3 oggetti');const arr=forgeSelected.map(id=>game.inventory.find(x=>x.id===id));if(!arr.every(x=>x&&x.slot===arr[0].slot&&x.rarity===arr[0].rarity)||arr[0].rarity>=5)return showToast('Servono 3 oggetti dello stesso slot e rarità');arr.forEach(x=>game.inventory.splice(game.inventory.findIndex(y=>y.id===x.id),1));const item=makeItem(arr[0].slot);item.rarity=arr[0].rarity+1;item.power*=1.8;item.name=`${RARITIES[item.rarity]} ${SLOTS[item.slot]}`;game.inventory.push(item);showToast('Fusione riuscita: '+item.name)}forgeSelected=[];save();render()}

function equipItem(id){const it=game.inventory.find(x=>x.id===id);if(!it)return;const previous=game.gear[it.slot];if(previous)game.inventory.push(previous);game.gear[it.slot]=it;game.inventory.splice(game.inventory.findIndex(x=>x.id===id),1);save();render();showToast(it.name+' equipaggiato')}

function openModal(title,html){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>${title}</h2><div>${html}</div><button class="btn" id="modalClose">CHIUDI</button></div></div>`;document.getElementById('modalClose').onclick=()=>document.getElementById('modalRoot').innerHTML='' }
function shopAction(kind){if(kind==='starter'){if(game.starter)return showToast('Pacchetto già acquistato');game.starter=true;game.gold+=500;game.gems+=50;game.inventory.push(makeItem(0));showToast('Starter Pack simulato acquistato')}else if(kind==='gacha'){if(game.gems<100)return showToast('Cristalli insufficienti');game.gems-=100;game.pity++;let rarity=game.pity>=10?4:(Math.random()<.08?4:Math.random()<.2?3:1);if(rarity===4)game.pity=0;const it=makeItem(Math.floor(Math.random()*6));it.rarity=rarity;it.name=`${RARITIES[rarity]} ${SLOTS[it.slot]}`;game.inventory.push(it);openModal('Reliquia ottenuta',`<div class="loot-reveal rarity-${RARITY_CLASS[rarity]}">${it.name}</div>`)}else if(kind==='boost'){if(game.gems<250)return showToast('Cristalli insufficienti');game.gems-=250;game.offlineBoost=true;showToast('Boost offline attivato'};save();render()}

function onClick(e){const nav=e.target.closest('[data-tab]');if(nav)return go(nav.dataset.tab);const action=e.target.closest('[data-action]');if(action){if(action.dataset.action==='next')combatTick();if(action.dataset.action==='expedition')startExpedition();if(action.dataset.action==='forge')forgeAction()}const forgeModeBtn=e.target.closest('[data-forge-mode]');if(forgeModeBtn){forgeMode=forgeModeBtn.dataset.forgeMode;forgeSelected=[];render()}const forgeItem=e.target.closest('[data-forge-item]');if(forgeItem){const id=forgeItem.dataset.forgeItem;if(forgeSelected.includes(id))forgeSelected=forgeSelected.filter(x=>x!==id);else if(forgeSelected.length<3)forgeSelected.push(id);render()}const item=e.target.closest('[data-item]');if(item)equipItem(item.dataset.item);const region=e.target.closest('[data-region]');if(region){const i=+region.dataset.region;if(i<=game.region){game.region=i;game.node=1;game.enemyPct=100;save();render();showToast(REGIONS[i].name)}else showToast('Regione bloccata')}const node=e.target.closest('[data-node]');if(node){const n=+node.dataset.node;if(n<=game.node){game.node=n;game.enemyPct=100;save();render()}}const shop=e.target.closest('[data-shop]');if(shop)shopAction(shop.dataset.shop)}

document.addEventListener('click',onClick);
document.getElementById('claimOffline').addEventListener('click',()=>{const r=calculateOffline();game.gold+=r.gold;addXp(r.xp);game.offlineAt=Date.now();showToast('Ricompense riscattate: '+r.gold+' oro');save();initOffline();render()});
document.getElementById('settingsBtn').addEventListener('click',()=>openModal('Impostazioni','<p>Salvataggio locale attivo.</p><button class="btn secondary" id="resetSave">RESET DEMO</button><script></script>'));

document.addEventListener('click',e=>{if(e.target.id==='resetSave'){localStorage.removeItem('emberfall-save');location.reload()}});
setInterval(()=>{combatTick();claimExpedition()},2000);
setInterval(()=>{game.offlineAt=Math.min(game.offlineAt,Date.now());save()},30000);
render();initOffline();

